import * as React from "react";

export type ClockIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function ClockIcon({ size = 20, ...props }: ClockIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="12" r="8.5" /><path d="M12 7.5 L12 12 L15.5 14" />
    </svg>
  );
}
